Export exactly this CommonJS API:

module.exports = { createMergeCursor };

`createMergeCursor(streams)` receives an array of arrays. Each inner stream contains objects shaped as `{ key, value }` and is already sorted by nondecreasing finite numeric `key`.

The returned cursor has these methods:

- `next()`: returns `{ streamIndex, item }` for the lowest-key unconsumed item, or `null` when exhausted. If multiple next items have the same key, select the item from the lower stream index.
- `remaining()`: returns the total number of unconsumed items.

Advancing one cursor must never change the position of any other cursor, including another cursor created over the same `streams` value.

Use only the JavaScript standard library. Do not access the filesystem, network, clock, or randomness, and do not use external packages or frameworks.","reference_code":"function createMergeCursor(streams) {
  const offsets = streams.map(() => 0);

  return {
    next() {
      let selectedStream = -1;

      for (let streamIndex = 0; streamIndex < streams.length; streamIndex += 1) {
        const offset = offsets[streamIndex];
        if (offset >= streams[streamIndex].length) continue;

        if (
          selectedStream === -1 ||
          streams[streamIndex][offset].key <
            streams[selectedStream][offsets[selectedStream]].key
        ) {
          selectedStream = streamIndex;
        }
      }

      if (selectedStream === -1) return null;

      const item = streams[selectedStream][offsets[selectedStream]];
      offsets[selectedStream] += 1;
      return { streamIndex: selectedStream, item };
    },

    remaining() {
      let count = 0;
      for (let streamIndex = 0; streamIndex < streams.length; streamIndex += 1) {
        count += streams[streamIndex].length - offsets[streamIndex];
      }
      return count;
    }
  };
}

module.exports = { createMergeCursor };
