The exported `mergeRankedEntries(left, right)` function receives two arrays of valid `{ id, score }` entries. It must return each distinct ID exactly once. For a repeated ID, select its occurrence with the highest score; if scores tie, prefer an occurrence from `left`; if still tied, prefer the earlier position in that input array.

Order the selected entries by descending score. Equal-score entries are ordered first by their selected source (`left` before `right`) and then by their original position. Return plain `{ id, score }` objects.

The current implementation incorrectly resolves repeated IDs:

```javascript
function mergeRankedEntries(left, right) {
  const tagged = [];

  for (let index = 0; index < left.length; index += 1) {
    tagged.push({ ...left[index], source: 0, position: index });
  }
  for (let index = 0; index < right.length; index += 1) {
    tagged.push({ ...right[index], source: 1, position: index });
  }

  const selected = new Map();
  for (const entry of tagged) {
    if (!selected.has(entry.id)) {
      selected.set(entry.id, entry);
    }
  }

  return Array.from(selected.values())
    .sort((a, b) => {
      if (a.score !== b.score) return b.score - a.score;
      if (a.source !== b.source) return a.source - b.source;
      return a.position - b.position;
    })
    .map(({ id, score }) => ({ id, score }));
}

module.exports = { mergeRankedEntries };
```

