Export exactly this CommonJS API:

module.exports = { parseChannelManifest };

`parseChannelManifest(text, groups)` parses valid manifest text consisting of nonempty lines in this grammar:

`channel = token, token, ...`

Whitespace surrounding a channel, `=`, commas, and tokens is ignored. Channel names are unique. A token beginning with `@` is a group reference: `@name` expands, in place, to all strings in `groups[name]`. All referenced groups exist. Other tokens are included literally after trimming.

Return a plain object whose keys are channel names and whose values are the expanded token arrays in manifest order. The returned object and every returned array must be frozen. Every returned array must also be independently owned: it must not alias an array from `groups`, and parsing must not mutate or freeze any caller-owned group array.

Use only the JavaScript standard library. Do not access the filesystem, network, clock, or randomness, and do not use external packages or frameworks.","reference_code":"function parseChannelManifest(text, groups) {
  const result = {};
  const lines = text.split('\n').filter((line) => line.trim() !== '');

  for (const line of lines) {
    const separator = line.indexOf('=');
    const channel = line.slice(0, separator).trim();
    const tokens = line
      .slice(separator + 1)
      .split(',')
      .map((token) => token.trim());

    const expanded = tokens.map((token) => {
      if (token.startsWith('@')) {
        return groups[token.slice(1)];
      }
      return [token];
    });

    const values = expanded.flat();
    result[channel] = Object.freeze(values);
  }

  return Object.freeze(result);
}

module.exports = { parseChannelManifest };
","known_bad_code":"function parseChannelManifest(text, groups) {
  const result = {};
  const lines = text.split('\n').filter((line) => line.trim() !== '');

  for (const line of lines) {
    const separator = line.indexOf('=');
    const channel = line.slice(0, separator).trim();
    const tokens = line
      .slice(separator + 1)
      .split(',')
      .map((token) => token.trim());

    const expanded = tokens.map((token) => {
      if (token.startsWith('@')) {
        return groups[token.slice(1)];
      }
      return [token];
    });

    const values = expanded.length === 1 ? expanded[0] : expanded.flat();
    result[channel] = Object.freeze(values);
  }

  return Object.freeze(result);
}

module.exports = { parseChannelManifest };
","known_bad_label":"A channel containing one group reference reuses and freezes the caller's group array instead of producing an independently owned frozen array."}]}

