});
assert.ok(Object.isFrozen(parsed));
for (const values of Object.values(parsed)) {
  assert.ok(Object.isFrozen(values));
}

assert.notStrictEqual(parsed.primary, originalCore);
assert.notStrictEqual(parsed.secondary, originalSingle);
assert.notStrictEqual(parsed['empty-expansion'], originalEmpty);
assert.notStrictEqual(parsed['group-only'], originalCore);
assert.notStrictEqual(parsed.primary, parsed['group-only']);
