assert.strictEqual(groups.single, originalSingle);
assert.strictEqual(groups.empty, originalEmpty);
assert.ok(!Object.isFrozen(groups));
assert.ok(!Object.isFrozen(groups.core));
assert.ok(!Object.isFrozen(groups.single));
assert.ok(!Object.isFrozen(groups.empty));

originalCore.push('added-later');
