{"items":[{"id":"cap-v2-parsing_and_encoding-javascript-generation-02","test_code":"'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['decodeMemo']);
assert.strictEqual(typeof api.decodeMemo, 'function');

const { decodeMemo } = api;

const defaults = { important: false, labels: ['default', 'inbox'] };
const defaultsSnapshot = { important: false, labels: ['default', 'inbox'] };

const normalized = decodeMemo(
  JSON.stringify({
    title: 'Plan',
    author: 'Ada',
    description: 'First draft',
    important: true,
    labels: ['work', 'urgent'],
    ignored: 'not returned'
  }),
  defaults
);

assert.deepStrictEqual(normalized, {
  title: 'Plan',
  author: 'Ada',
  description: 'First draft',
  important: true,
  labels: ['work', 'urgent']
});
assert.deepStrictEqual(Object.keys(normalized), [
  'title',
  'author',
  'description',
  'important',
  'labels'
]);
assert.deepStrictEqual(defaults, defaultsSnapshot);

const fromDefaults = decodeMemo(
  '{"title":"Empty labels default","author":"Grace","description":"Defaults apply"}',
  defaults
);
assert.deepStrictEqual(fromDefaults, {
  title: 'Empty labels default',
  author: 'Grace',
  description: 'Defaults apply',
  important: false,
  labels: ['default', 'inbox']
});
assert.notStrictEqual(fromDefaults.labels, defaults.labels);

fromDefaults.labels.push('changed');
assert.deepStrictEqual(defaults, defaultsSnapshot);

const explicitFalseAndEmpty = decodeMemo(
  '{"title":"Boundary","author":"Lin","description":"","important":false,"labels":[]}',
  { important: true, labels: ['fallback'] }
);
assert.deepStrictEqual(explicitFalseAndEmpty, {
  title: 'Boundary',
  author: 'Lin',
  description: '',
  important: false,
  labels: []
});

const originalParse = JSON.parse;
let parsedLabels;
JSON.parse = function captureParsedLabels(text, reviver) {
  const value = originalParse(text, reviver);
  parsedLabels = value.labels;
  return value;
};

let capturedResult;
try {
  capturedResult = decodeMemo(
    '{"title":"Aliasing","author":"Test","description":"Input array","labels":["x"]}',
    { important: true, labels: [] }
  );
} finally {
  JSON.parse = originalParse;
}

assert.deepStrictEqual(capturedResult.labels, ['x']);
assert.notStrictEqual(capturedResult.labels, parsedLabels);
capturedResult.labels.push('y');
assert.deepStrictEqual(parsedLabels, ['x']);
