const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['mergeTimelines']);
assert.strictEqual(typeof api.mergeTimelines, 'function');

const { mergeTimelines } = api;

assert.deepStrictEqual(mergeTimelines([], []), []);

const onlyLeft = [{ time: 1, id: 'l1' }, { time: 3, id: 'l3' }];
const onlyLeftResult = mergeTimelines(onlyLeft, []);
assert.deepStrictEqual(onlyLeftResult, onlyLeft);
assert.notStrictEqual(onlyLeftResult, onlyLeft);

const onlyRight = [{ time: -2, id: 'r-2' }, { time: 0, id: 'r0' }];
const onlyRightResult = mergeTimelines([], onlyRight);
assert.deepStrictEqual(onlyRightResult, onlyRight);
assert.notStrictEqual(onlyRightResult, onlyRight);

const left = [
  { time: -5, id: 'l-5' },
  { time: 2, id: 'l2a' },
  { time: 2, id: 'l2b' },
  { time: 7, id: 'l7' }
];
const right = [
  { time: -4, id: 'r-4' },
  { time: 2, id: 'r2a' },
  { time: 2, id: 'r2b' },
  { time: 9, id: 'r9' }
];
const leftSnapshot = left.slice();
const rightSnapshot = right.slice();

const merged = mergeTimelines(left, right);
assert.deepStrictEqual(
  merged.map((entry) => entry.id),
  ['l-5', 'r-4', 'l2a', 'l2b', 'r2a', 'r2b', 'l7', 'r9']
);
assert.deepStrictEqual(left, leftSnapshot);
assert.deepStrictEqual(right, rightSnapshot);
assert.notStrictEqual(merged, left);
assert.notStrictEqual(merged, right);
assert.strictEqual(merged[0], left[0]);
assert.strictEqual(merged[1], right[0]);

const allEqualLeft = [
  { time: 4, id: 'left-first' },
  { time: 4, id: 'left-second' }
];
const allEqualRight = [
  { time: 4, id: 'right-first' },
  { time: 4, id: 'right-second' }
];
assert.deepStrictEqual(
  mergeTimelines(allEqualLeft, allEqualRight).map((entry) => entry.id),
  ['left-first', 'left-second', 'right-first', 'right-second']
);

const boundaryLeft = [{ time: Number.NEGATIVE_INFINITY, id: 'min' }];
const boundaryRight = [{ time: Number.MAX_VALUE, id: 'max' }];
assert.deepStrictEqual(
  mergeTimelines(boundaryLeft, boundaryRight).map((entry) => entry.id),
  ['min', 'max']
);
