const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['stablePartition']);
assert.strictEqual(typeof api.stablePartition, 'function');

const { stablePartition } = api;

const emptyCalls = [];
const emptyResult = stablePartition([], (element, index) => {
  emptyCalls.push([element, index]);
  return true;
});
assert.deepStrictEqual(emptyResult, []);
assert.deepStrictEqual(emptyCalls, []);

const items = [5, 2, 7, 4, 1, 6];
const snapshot = items.slice();
const calls = [];
const result = stablePartition(items, (element, index) => {
  calls.push([element, index]);
  return element % 2 === 0;
});

assert.deepStrictEqual(result, [2, 4, 6, 5, 7, 1]);
assert.deepStrictEqual(calls, [
  [5, 0],
  [2, 1],
  [7, 2],
  [4, 3],
  [1, 4],
  [6, 5]
]);
assert.deepStrictEqual(items, snapshot);
assert.notStrictEqual(result, items);

const objects = [
  { id: 'a', group: 2 },
  { id: 'b', group: 1 },
  { id: 'c', group: 2 },
  { id: 'd', group: 1 }
];
const objectResult = stablePartition(objects, (item) => item.group === 1);
assert.deepStrictEqual(objectResult.map((item) => item.id), ['b', 'd', 'a', 'c']);
assert.strictEqual(objectResult[0], objects[1]);
assert.strictEqual(objectResult[1], objects[3]);
assert.strictEqual(objectResult[2], objects[0]);
assert.strictEqual(objectResult[3], objects[2]);

let allTrueCalls = 0;
const allTrueInput = ['x', 'y'];
const allTrueResult = stablePartition(allTrueInput, () => {
  allTrueCalls += 1;
  return 'truthy';
});
assert.deepStrictEqual(allTrueResult, ['x', 'y']);
assert.strictEqual(allTrueCalls, 2);
assert.notStrictEqual(allTrueResult, allTrueInput);

let allFalseCalls = 0;
const allFalseInput = ['x', 'y'];
const allFalseResult = stablePartition(allFalseInput, () => {
  allFalseCalls += 1;
  return 0;
});
assert.deepStrictEqual(allFalseResult, ['x', 'y']);
assert.strictEqual(allFalseCalls, 2);
assert.notStrictEqual(allFalseResult, allFalseInput);
"}]}

